import {
  GALLERY_CATALOG,
  galleryCatalogSchema,
  initialParams,
  primitiveById,
} from './gallery-catalog';

/**
 * The snapshot is generated by `ui:gallery`; this test is the web-side contract.
 * A render-worker test keeps the file equal to `catalog.ts`.
 */
describe('gallery catalogue snapshot', () => {
  it('parses with the published schema', () => {
    expect(galleryCatalogSchema.safeParse(GALLERY_CATALOG).success).toBe(true);
  });

  it('gives every primitive the director sees a prompt and a purpose', () => {
    const offered = GALLERY_CATALOG.primitives.filter(
      (primitive) => primitive.offeredToDirector,
    );

    expect(offered.length).toBeGreaterThan(0);

    for (const primitive of offered) {
      expect(primitive.semantics.length).toBeGreaterThan(0);
      expect(primitive.prompt.join('\n')).toContain(`- ${primitive.id} — `);
    }
  });

  it('keeps the asset primitives out of the prompt', () => {
    const hidden = GALLERY_CATALOG.primitives.filter(
      (primitive) => !primitive.offeredToDirector,
    );

    expect(hidden.length).toBeGreaterThan(0);

    for (const primitive of hidden) {
      expect(primitive.prompt).toEqual([]);
    }
  });

  it('declares a channel and a path for the iframe', () => {
    expect(GALLERY_CATALOG.preview.channel.length).toBeGreaterThan(0);
    expect(GALLERY_CATALOG.preview.path.endsWith('.html')).toBe(true);
  });

  it('seeds params from the declared defaults', () => {
    const primitive = GALLERY_CATALOG.primitives.find(
      (item) => item.offeredToDirector,
    );

    if (primitive === undefined) {
      throw new Error('the catalogue offers no primitive to the director');
    }

    expect(initialParams(primitive)).toEqual(
      Object.fromEntries(
        primitive.parameters.map((parameter) => [
          parameter.name,
          parameter.initial,
        ]),
      ),
    );
    expect(primitiveById(primitive.id)).toEqual(primitive);
    expect(primitiveById('no-such-primitive')).toBeNull();
  });
});
